schema_ddl:
CREATE TABLE facolta (id INT PRIMARY KEY, nome_facolta TEXT NOT NULL);

CREATE TABLE studenti (id INT PRIMARY KEY, nome TEXT NOT NULL, cognome TEXT NOT NULL, facolta_id INT);

CREATE TABLE corsi (id INT PRIMARY KEY, titolo_corso TEXT NOT NULL, crediti INT CHECK (crediti > 0));

CREATE TABLE esami (id INT PRIMARY KEY, studente_id INT, corso_id INT, voto_esame INT CHECK (voto_esame BETWEEN 18 AND 30), data_appello DATE NOT NULL);
